let settings=healthStore.getSnapshot().configured?{...defaultSettings}:{...defaultSettings,...readLocal('cosmovital-settings-v1',{})};
settings=normalizeSettings(settings);
function normalizeSettings(value){const next={...defaultSettings,...value};try{new Intl.DateTimeFormat('en',{timeZone:next.timeZone})}catch{next.timeZone='UTC'}if(!['°C','°F'].includes(next.temperatureUnit))next.temperatureUnit='°C';if(!['mg/dL','mmol/L'].includes(next.glucoseUnit))next.glucoseUnit='mg/dL';return next}
