function renderShell(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=`CosmoVital — ${t('Crew Health Workspace','صحة طاقم الفضاء')}`;
$('#app').innerHTML=`<div class="app-shell"><div class="mobile-overlay ${menuOpen?'visible':''}" data-action="menu-close"></div><aside class="sidebar ${menuOpen?'open':''}" aria-label="${t('Main navigation','القائمة الرئيسية')}"><a href="#overview" class="brand"><img src="assets/favicon.svg" alt=""><div><div class="brand-name">cosmo<span>vital</span></div><div class="brand-sub">HUMAN HEALTH. BEYOND EARTH.</div></div></a><p class="nav-label">${t('MISSION CONTROL','مركز المتابعة')}</p><nav class="nav-list">${navs.slice(0,4).map(navItem).join('')}</nav><div class="nav-divider"></div><p class="nav-label">${t('YOUR WORKSPACE','مساحة العمل')}</p><nav class="nav-list">${navs.slice(4).map(navItem).join('')}<button class="nav-item" data-action="settings">${icon('settings')}${t('Workspace settings','إعدادات مساحة العمل')}</button></nav><div class="sidebar-bottom"><div class="mission-card"><div class="mission-top"><span class="status-dot"></span>${t('MISSION ENVIRONMENT','بيئة المهمة')}</div><h4>${environmentName()}</h4><p>${settings.start?missionDay():t('Your health. Your perspective.','صحتك، من منظورك.')}</p><div class="mission-orbit" aria-hidden="true"></div></div><button class="profile" data-action="settings"><span class="avatar">${esc(settings.name?.slice(0,2).toUpperCase()||'EX')}</span><span><strong>${esc(settings.name||'Explorer')}</strong><small>${t('Personal workspace','مساحة عمل شخصية')}</small></span>${icon('settings')}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="${t('Open navigation','افتح القائمة')}">${icon('menu')}</button>${icon('home')}<span>${t('Workspace','مساحة العمل')}</span><span> / </span><strong id="breadcrumb-current"></strong></div><div class="top-actions"><time class="clock" id="utc-clock"></time><span class="local-tag"><span class="status-dot"></span>${healthStore.getSnapshot().configured?t('Account storage','تخزين الحساب'):t('On this device','على هذا الجهاز')}</span><button class="lang-btn" data-action="language" aria-label="${t('Switch to Arabic','التبديل للإنجليزية')}">${t('العربية','English')}</button><button class="icon-btn" data-action="help" aria-label="${t('Open interim medical guidance','افتح إرشادات لحد وصول المساعدة')}">${icon('shield')}</button>${account.header()}</div></header><main id="main" class="main" tabindex="-1"></main></div></div>`;renderMain();updateClock()}
function navItem(n){return `<a class="nav-item ${view===n[0]?'active':''}" href="#${n[0]}" ${view===n[0]?'aria-current="page"':''}>${icon(n[1])}${t(n[2],n[3])}${n[0]==='research'?'<span class="badge">NASA</span>':n[0]==='training'?'<span class="badge">SIM</span>':''}</a>`}
function missionDay(){const d=Math.max(1,Math.floor((Date.now()-Date.parse(settings.start+'T00:00:00'))/86400000)+1);return t(`Mission day ${d} · personal profile`,`يوم المهمة ${d} · ملف شخصي`)}
function updateClock(){const el=$('#utc-clock');if(el)el.textContent=new Date().toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'})+' UTC'}setInterval(updateClock,15000);
function heading(title,subtitle,eyebrow=t('CREW HEALTH WORKSPACE','متابعة صحة طاقم الفضاء')){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-buttons"><button class="btn btn-light" data-action="export">${icon('download')}${t('Export report','تصدير تقرير')}</button><button class="btn btn-primary" data-action="log">${icon('plus')}${t('Log a reading','سجّل قياسًا')}</button></div></div>`}
function persistenceBanner(){const state=healthStore.getSnapshot(),offline=navigator.onLine===false;return `<div class="persistence-banner ${offline?'offline':''}" role="status"><span>${icon(offline?'wifi':'shield')}${offline?t('Offline','بدون اتصال')+' · ':''}${state.configured?(state.saving?t('Saving to your account…','جارٍ الحفظ في حسابك…'):state.user?state.lastSync?t('Account loaded · last confirmed sync: ','الحساب محمّل · آخر تأكيد مزامنة: ')+fmtDate(state.lastSync)+' '+fmtTime(state.lastSync):t('Account storage','تخزين الحساب'):t('Sign in for private account data','سجّل الدخول لبيانات حسابك الخاصة')):t('Local workspace · cloud accounts not configured','مساحة محلية · الحسابات السحابية غير مفعّلة')}</span><button class="text-link" data-action="refresh-account">${t('Reload saved data','أعد تحميل البيانات المحفوظة')}</button></div>`}
