function renderMain(){const nav=navs.find(n=>n[0]===view)||navs[0];$('#breadcrumb-current').textContent=t(nav[2],nav[3]);document.querySelectorAll('.nav-item[href]').forEach(el=>{const on=el.hash===`#${view}`;el.classList.toggle('active',on);if(on)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});const renderers={...account.views,alerts:()=>healthUI.alertsView(),overview:overviewView,trends:trendsView,body:bodyView,routine:routineView,help:helpView,records:recordsView,research:researchView,...workspace.views};if(account.protected(view)){view='login';if(location.hash!=='#login')location.hash='login'}const state=healthStore.getSnapshot();if(state.configured&&state.status==='loading'&&!Object.keys(account.views).includes(view)){ $('#main').innerHTML=`<div class="loading-line" role="status">${t('Loading your private workspace…','جارٍ تحميل مساحة عملك الخاصة…')}</div>`;return}$('#main').innerHTML=persistenceBanner()+(storageError?`<div class="warning-banner">${esc(storageError)} ${t('Saving is blocked to protect existing data.','تم إيقاف الحفظ لحماية بياناتك.')}</div>`:'')+(renderers[view]||overviewView)()+footer()+(state.configured&&!state.user?'':printReport());if(view==='research'&&!research&&!researchError)loadResearch()}
function overviewView(){return `${heading(t('Your mission. Your wellbeing.','مهمتك تبدأ بصحتك.'),t('A clearer picture of your health, one check-in at a time.','صورة أوضح لصحتك، مع كل قياس تسجّله.'))}${helpEntry()}<section class="hero"><img class="hero-bg" src="assets/earth-orbit.jpg" alt="${t('Earth photographed from orbit by NASA','صورة للأرض من المدار التقطتها ناسا')}"><div class="hero-content"><div class="eyebrow"><span class="status-dot"></span>${t('A HUMAN PERSPECTIVE ON SPACE HEALTH','منظور إنساني للصحة في الفضاء')}</div><h2>${t('Far from Earth.<br><em>Closer to your health.</em>','بعيدًا عن الأرض.<br><em>أقرب لفهم صحتك.</em>')}</h2><p>${t('Understand your measurements, build healthy routines, and make every check-in count.','افهم قياساتك، وابنِ روتينًا صحيًا، وخلّي كل تسجيل خطوة لوعي أفضل.')}</p><button class="btn btn-mint" data-action="log">${t('Start your check-in','ابدأ تسجيل قياساتك')}${icon('arrow','ico-arrow')}</button></div><div class="hero-annotation">${icon('planet')} ${t('EXPLORATION STARTS WITH YOU','الاستكشاف يبدأ بك')}</div><div class="hero-coordinates">${t('EARTH, OUR POINT OF REFERENCE','الأرض، نقطة مرجعنا')}<small>NASA IMAGERY / ${t('RESEARCH-INSPIRED DESIGN','تصميم مستلهم من البحث العلمي')}</small></div></section><div class="section-heading"><h2>${t('Your health at a glance','صحتك في لمحة')}</h2><span class="subtle">${lastRecord()?t('Latest check-in: ','آخر تسجيل: ')+fmtDate(lastRecord().timestamp)+' · '+fmtTime(lastRecord().timestamp):t('Ready for your first check-in','جاهز لأول تسجيل')}</span></div><section class="metric-grid" aria-label="${t('Latest self-reported measurements','آخر القياسات المدخلة')}">${['heart','oxygen','sleep','temp'].map(metricCard).join('')}</section>${workspace.overview()}<div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>${t('Health trends','اتجاهات صحتك')}</h2><p>${t('Small changes, a bigger picture.','تغيّرات صغيرة، وصورة أوسع.')}</p></div>${periodControl()}</div>${chartControls()}${renderChart()}<div class="chart-footer"><span>${t('Self-reported measurements · not a diagnosis','قياسات شخصية · ليست تشخيصًا')}</span><a class="text-link" href="#trends">${t('View trends','كل الاتجاهات')}${icon('arrow','ico-arrow')}</a></div></section><section class="panel body-panel"><div class="panel-head"><div><h2>${t('Body insights','افهم جسمك')}</h2><p>${t('Connect the dots between your body & space.','افهم العلاقة بين جسمك والفضاء.')}</p></div><span class="pill green">${t('Explore','استكشف')}</span></div><div class="body-preview">${bodySVG(true)}<div class="system-list">${[['heart','Cardiovascular','القلب والدورة الدموية','heart'],['brain','Mind & recovery','الذهن والتعافي','sleep'],['oxygen','Respiratory','الجهاز التنفسي','oxygen'],['bone','Bones & muscles','العظام والعضلات',null]].map(([ic,en,ar,k])=>`<div class="system-item">${icon(ic)}<div><strong>${t(en,ar)}</strong><small>${k&&latest(k)?t('Measurement recorded','يوجد قياس مسجّل'):t('Awaiting measurements','في انتظار القياسات')}</small></div><span class="tiny-ring"></span></div>`).join('')}</div></div><div class="panel-bottom-link"><a class="text-link" href="#body">${t('Explore your body map','استكشف خريطة جسمك')}${icon('arrow','ico-arrow')}</a></div></section></div><div class="lower-grid"><section class="panel"><div class="panel-head"><div><h2>${t('Your daily orbit','روتينك اليومي')}</h2><p>${t('A little consistency goes a long way.','الاستمرار بيصنع فرقًا.')}</p></div>${taskProgress()}</div><div class="routine-list">${taskRows(true)}</div></section><aside class="insight-card"><div class="eyebrow">${icon('spark')}${t('GROUNDED IN SCIENCE','أساسه العلم')}</div><h3>${t('Space changes the environment.<br>Awareness changes the response.','الفضاء بيغيّر البيئة.<br>والوعي بيحسّن الاستجابة.')}</h3><p>${t('NASA identifies five hazards of human spaceflight. Explore the research behind a more informed health check-in.','ناسا بتحدد خمسة مخاطر رئيسية لرحلات الفضاء البشرية. اكتشف البحث العلمي وراء متابعة صحية أكثر وعيًا.')}</p><a class="text-link" href="#research">${t('Explore the research','استكشف الأبحاث')}${icon('arrow','ico-arrow')}</a><div class="insight-orbit" aria-hidden="true"></div></aside></div>${recentAlerts()}`}
function metricCard(k){const m=METRICS[k],r=latest(k),v=r?.values[k],shown=k==='temp'&&v!=null&&settings.temperatureUnit==='°F'?Number((v*9/5+32).toFixed(2)):v,shownUnit=k==='temp'?settings.temperatureUnit:m.unit,color=m.color,ico={heart:'heart',oxygen:'oxygen',sleep:'moon',temp:'temp'}[k];const s=v==null?'unassessed':k==='heart'&&r.context!=='resting'?'unassessed':statusFor(k,v);const label=v==null?t('Not recorded','لم يُسجّل'):s==='urgent'?t('Medical attention','انتباه طبي'):s==='review'?t('Review suggested','يُفضّل المراجعة'):t('Recorded','مسجّل');return `<button class="metric-card" data-action="metric" data-metric="${k}" aria-label="${esc(metricLabel(k))}: ${v??t('not recorded','غير مسجّل')}"><div class="metric-head"><span class="metric-icon" style="color:${color};background:${color}16">${icon(ico)}</span>${metricLabel(k)}<span class="metric-more">···</span></div><div class="metric-value" dir="ltr">${shown??'— —'}<span>${shownUnit}</span></div><div class="metric-bottom"><span class="pill ${s==='urgent'?'red':s==='review'?'orange':v!=null?'green':''}"><span style="font-size:7px">●</span>${label}</span><span>${r?dateKey(r.timestamp,settings.timeZone)===localDate()?fmtTime(r.timestamp):fmtDate(r.timestamp):t('No data yet','لا توجد بيانات')}</span></div></button>`}
function periodControl(){return `<div class="segmented" aria-label="${t('Time range','الفترة الزمنية')}">${[['24',t('24 hours','٢٤ ساعة')],['7',t('7 days','٧ أيام')],['30',t('30 days','٣٠ يوم')],['all',t('All','الكل')]].map(([v,l])=>`<button data-action="period" data-period="${v}" class="${v===period?'active':''}" aria-pressed="${v===period}">${l}</button>`).join('')}</div>`}
function chartControls(){const keys=availableMetrics(records);if(!keys.includes(metric)&&keys.length)metric=keys[0];return `<div class="chart-toolbar"><select aria-label="${t('Measurement to chart','نوع القياس للرسم')}" id="chart-metric" ${keys.length?'':'disabled'}>${keys.length?keys.map(k=>`<option value="${k}" ${k===metric?'selected':''}>${k==='bp'?t('Blood pressure · systolic / diastolic','ضغط الدم · انقباضي / انبساطي'):metricLabel(k)}</option>`).join(''):`<option>${t('No measurements recorded','لم تُسجّل قياسات')}</option>`}</select><span class="legend">${esc(settings.timeZone)} · ${t('Actual observations','قياسات فعلية')}</span></div>`}
function chartPoints(){return records.filter(r=>r.values[metric]!=null&&(period==='all'||Date.parse(r.timestamp)>=Date.now()-Number(period)*86400000)).map(r=>({value:r.values[metric],time:Date.parse(r.timestamp)}))}
function makeChart(points,{height=230,color='#5e9c85',label=metricLabel(metric),unit=METRICS[metric].unit,seconds=false}={}){const w=650,h=height,p={l:43,r:18,t:20,b:37},iw=w-p.l-p.r,ih=h-p.t-p.b;const vals=points.map(p=>p.value);let low=vals.length?Math.min(...vals):0,high=vals.length?Math.max(...vals):100;const pad=Math.max((high-low)*.25,high>20?3:1);low=Math.max(0,low-pad);high+=pad;const minTime=points.length?Math.min(...points.map(p=>p.time)):0,maxTime=points.length?Math.max(...points.map(p=>p.time)):1;const x=time=>p.l+(maxTime===minTime?.5:(time-minTime)/(maxTime-minTime))*iw,y=v=>p.t+ih-(v-low)/(high-low)*ih;const ticks=Array.from({length:5},(_,i)=>{const yy=p.t+ih*i/4;return `<line x1="${p.l}" x2="${w-p.r}" y1="${yy}" y2="${yy}" stroke="#edf1ef" stroke-dasharray="3 4"/><text x="${p.l-11}" y="${yy+3}" text-anchor="end">${points.length?Number((high-(high-low)*i/4).toFixed(1)):['100','75','50','25','0'][i]}</text>`}).join('');const labels=points.length?Array.from({length:Math.min(points.length,5)},(_,i)=>{const time=minTime+(maxTime-minTime)*i/Math.max(1,Math.min(points.length,5)-1);return `<text x="${x(time)}" y="${h-12}" text-anchor="middle">${seconds?Math.round(time/60000)+' min':new Date(time).toLocaleDateString(locale(),{day:'numeric',month:'short'})}</text>`}).join(''):'';const d=points.map((p,i)=>`${i?'L':'M'}${x(p.time).toFixed(2)},${y(p.value).toFixed(2)}`).join(' ');const area=points.length>1?`<path d="${d}L${x(points.at(-1).time)},${p.t+ih}L${x(points[0].time)},${p.t+ih}Z" fill="url(#chart-fill)"/>`:'';return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label+' · '+unit+' · '+points.length+' '+t('observations','قياسات'))}" direction="ltr"><title>${esc(label)} · ${unit}</title><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${color}" stop-opacity=".17"/><stop offset="1" stop-color="${color}" stop-opacity=".01"/></linearGradient></defs>${ticks}${labels}${area}<path d="${d}" fill="none" stroke="${color}" stroke-width="2" stroke-linejoin="round"/>${points.map(p=>`<g><circle class="chart-point" tabindex="0" role="img" aria-label="${esc((seconds?p.time/1000+' s':new Date(p.time).toLocaleString(locale()))+': '+p.value+' '+unit)}" cx="${x(p.time)}" cy="${y(p.value)}" r="${points.length>60?1.5:3.5}" fill="${color}" stroke="#fff" stroke-width="1.5"><title>${p.value} ${unit} · ${seconds?p.time/1000+' s':new Date(p.time).toLocaleString(locale())}</title></circle><text class="chart-dot-label" x="${Math.min(w-65,Math.max(70,x(p.time)))}" y="${Math.max(12,y(p.value)-12)}" text-anchor="middle" style="fill:#345e49;font-size:12px;font-weight:700">${p.value} ${unit}</text></g>`).join('')}</svg>`}
function renderChart(full=false){try{return renderHealthChart(buildChartModel(records,metric,{range:period,timeZone:settings.timeZone,unitPreferences:settings,userId:healthStore.getSnapshot().user?.id}),{lang,locale:locale()})}catch(error){return `<div class="notice orange" role="alert">${esc(error.message)}</div>`}}
const systems={cardio:{icon:'heart',en:'Cardiovascular system',ar:'القلب والدورة الدموية',desc:['Fluid shifts and changes in gravity can affect cardiovascular function. Track readings alongside the measurement context, not in isolation.','تغيّرات الجاذبية وتوزيع سوائل الجسم قد تؤثر على القلب والدورة الدموية. تابع القياسات مع ظروف تسجيلها.'],keys:['heart','sys','dia','hrv'],guide:['Rest quietly before measuring. Use a validated cuff, keep the arm supported at heart level, and record both pressure values.','استرح قبل القياس. استخدم جهاز ضغط موثوقًا، واسند ذراعك عند مستوى القلب، وسجّل الضغط الانقباضي والانبساطي.'],source:'https://www.heart.org/en/health-topics/high-blood-pressure/monitoring-your-blood-pressure-at-home'},mind:{icon:'brain',en:'Mind & recovery',ar:'الذهن والتعافي',desc:['Isolation, confinement, workload, and disrupted sleep can affect how you feel. Mood and sleep check-ins support a conversation; they cannot diagnose mental health conditions.','العزلة والضغط واضطراب النوم ممكن يؤثروا على حالتك. تسجيل النوم والمزاج يساعد في المتابعة، لكنه مش تشخيص نفسي.'],keys:['sleep','mood','eda'],guide:['Record your actual sleep time and how you feel today. Use the same time each day, and raise persistent changes with the medical team.','سجّل ساعات نومك الفعلية وشعورك اليوم. حاول التسجيل في نفس التوقيت، وناقش التغيّرات المستمرة مع الفريق الطبي.'],source:'https://www.nasa.gov/hrp/hazards/'},respiratory:{icon:'oxygen',en:'Respiratory system',ar:'الجهاز التنفسي',desc:['A pulse oximeter estimates oxygen saturation. Motion, cold skin, nail products, skin pigmentation, and device quality can affect accuracy. Symptoms matter even when a reading appears reassuring.','مقياس التأكسج يقدّر تشبع الأكسجين. الحركة وبرودة الجلد وطلاء الأظافر ولون الجلد وجودة الجهاز قد تؤثر على الدقة. الأعراض مهمة مهما كانت القراءة.'],keys:['oxygen'],guide:['Follow your device instructions. Keep the hand warm and still, wait for a stable reading, and record the result. Unexpected results or symptoms need medical review.','اتبع تعليمات جهازك. حافظ على يد دافئة وثابتة وانتظر استقرار القراءة. النتائج غير المتوقعة أو الأعراض تحتاج مراجعة طبية.'],source:'https://medlineplus.gov/lab-tests/pulse-oximetry/'},bone:{icon:'bone',en:'Bones & muscles',ar:'العظام والعضلات',desc:['Reduced loading in altered gravity can affect bones and muscles. Routine exercise and mission-approved monitoring are important. Vital signs alone cannot measure bone density or muscle strength.','انخفاض الحمل في الجاذبية المتغيرة قد يؤثر على العظام والعضلات. المتابعة والتمرين حسب بروتوكول المهمة مهمان. العلامات الحيوية لا تقيس كثافة العظام أو قوة العضلات.'],keys:[],guide:['Follow the prescribed mission exercise plan. Log completion in your daily routine; bone density and strength require appropriate clinical measurements.','اتبع خطة تمارين المهمة المعتمدة. سجّل إتمامها في الروتين اليومي؛ كثافة العظام وقوة العضلات تحتاجان قياسات متخصصة.'],source:'https://www.nasa.gov/hrp/hazards/'},metabolic:{icon:'temp',en:'Metabolic & body signals',ar:'إشارات الجسم والتمثيل الغذائي',desc:['Temperature and glucose measurements require context. Measurement site, device, meals, medicines, and activity can change interpretation.','درجة الحرارة والسكر محتاجين سياق واضح. موضع القياس والجهاز والأكل والأدوية والنشاط بيغيّروا تفسير النتائج.'],keys:['temp','glucose'],guide:['Record the measurement method and whether glucose was measured fasting or after food in your notes. Glucose is displayed without automatic interpretation.','سجّل طريقة القياس، وهل السكر مقاس صائمًا أو بعد الأكل في الملاحظات. السكر يُعرض بدون تفسير تلقائي.'],source:'https://medlineplus.gov/lab-tests/blood-glucose-test/'}};
function bodySVG(mini=false){const dots=[['mind',100,30],['respiratory',87,108],['cardio',109,115],['metabolic',100,163],['bone',116,252]];return `<svg class="body-anatomy ${mini?'body-mini':''}" viewBox="0 0 200 370" ${mini?'aria-hidden="true"':`role="group" aria-label="${t('Interactive body map. Choose a system.','خريطة الجسم التفاعلية. اختر جهازًا.')}"`}><path class="body-outline" d="M100 9c-15 0-21 11-21 23 0 13 6 23 14 27v12L68 81c-8 3-11 12-13 23l-11 65-9 27c-2 6 1 11 5 10l10-8 14-32 13-45 2 57-7 69 7 77-2 26c-1 7 15 8 17 3l4-28-1-73 3-41 3 41-1 73 4 28c2 5 18 4 17-3l-2-26 7-77-7-69 2-57 13 45 14 32 10 8c4 1 7-4 5-10l-9-27-11-65c-2-11-5-20-13-23l-25-10V59c8-4 14-14 14-27 0-12-6-23-21-23Z"/><path class="body-inner" d="M100 74v108 M77 103c10-9 36-9 46 0 M76 133c10 10 38 10 48 0 M77 157c10 9 36 9 46 0 M78 181c12 10 33 10 44 0 M73 227l24 1 M103 228l24-1 M77 297h18 M105 297h18 M88 81l12 15 12-15 M87 16c-6 13-5 27 6 37 M113 16c6 13 5 27-6 37"/><path d="M100 112c-13-15-22 6 0 18 22-12 13-33 0-18" fill="#bddecf" opacity=".7"/><ellipse cx="87" cy="115" rx="8" ry="18" fill="#d1e6dc" opacity=".5"/><ellipse cx="113" cy="115" rx="8" ry="18" fill="#d1e6dc" opacity=".5"/>${dots.map(([id,x,y])=>`<g class="body-hotspot ${id===system?'selected':''}" ${mini?'':`role="button" tabindex="0" aria-label="${t(systems[id].en,systems[id].ar)}" aria-pressed="${id===system}" data-action="system" data-system="${id}"`}><circle class="hotspot-ring" cx="${x}" cy="${y}" r="8"/><circle class="hotspot-dot" cx="${x}" cy="${y}" r="3.2"/></g>`).join('')}</svg>`}
const taskDefs=[['checkin','heart','Daily health check-in','تسجيل القياسات اليومية','Record measurements using your usual device.','سجّل القياسات باستخدام جهازك المعتاد.','Self-monitoring','متابعة شخصية'],['movement','body','Mission movement plan','خطة الحركة والتمرين','Follow your mission-approved exercise routine.','اتبع روتين التمارين المعتمد لمهمتك.','Movement','الحركة'],['rest','moon','Protect your sleep window','اهتم بموعد النوم','Prepare for a consistent sleep and wake schedule.','استعد لمواعيد نوم واستيقاظ منتظمة.','Recovery','التعافي'],['connection','brain','Make time to connect','خصص وقتًا للتواصل','Check in with a crewmate and note how you feel.','تواصل مع أحد زملائك وسجّل شعورك.','Wellbeing','الصحة النفسية']];
const doneTasks=()=>tasks[localDate()]||[];
function taskProgress(){const n=doneTasks().length;return `<div class="progress-label"><div class="progress-track"><span style="width:${n/4*100}%"></span></div>${n}/4</div>`}
function taskRows(short=false){return taskDefs.slice(0,short?3:4).map(([id,ic,en,ar,den,dar,tag,tagar])=>`<div class="routine-row ${doneTasks().includes(id)?'completed':''}"><button class="task-check ${doneTasks().includes(id)?'checked':''}" data-action="task" data-task="${id}" role="checkbox" aria-checked="${doneTasks().includes(id)}" aria-label="${t(en,ar)}">${doneTasks().includes(id)?icon('check'):''}</button><div><h3>${t(en,ar)}</h3><p>${t(den,dar)}</p></div><span class="pill ${id==='checkin'?'green':id==='movement'?'orange':'blue'}">${t(tag,tagar)}</span></div>`).join('')}
function routineView(){const n=doneTasks().length;return `${heading(t('Stay in your daily orbit.','حافظ على روتينك اليومي.'),t('Personal reminders for a more consistent mission day.','تذكيرات شخصية ليوم أكثر انتظامًا.'))}<div class="routine-feature"><div><span class="eyebrow">${t('TODAY’S FLIGHT PLAN','خطة اليوم')}</span><h2>${t('Small habits. Meaningful progress.','عادات صغيرة، تقدّم له معنى.')}</h2><p>${new Date().toLocaleDateString(locale(),{weekday:'long',day:'numeric',month:'long'})} · ${t('Resets each local calendar day.','يبدأ من جديد مع كل يوم حسب توقيت جهازك.')}</p></div><div class="progress-circle" style="--progress:${n*25}%"><span>${n}/4</span></div></div><div class="page-grid"><section class="panel routine-full"><div class="panel-head"><div><h2>${t('Your daily checklist','قائمة يومك')}</h2><p>${t('Mark what you have actually completed.','حدّد المهام اللي خلّصتها فعلًا.')}</p></div>${taskProgress()}</div><div class="routine-list">${taskRows()}</div></section><aside class="panel panel-pad"><span class="eyebrow">${t('PERSONAL, NOT PRESCRIBED','تنظيم شخصي، مش وصفة علاجية')}</span><h2 style="font-size:18px;margin:12px 0">${t('Make room for recovery.','خصص وقتًا للتعافي.')}</h2><p class="helper-note">${t('These are general organizational prompts, not a medical or astronaut exercise prescription. Follow your approved mission plan. Checklist completion does not change a health score or resolve an alert.','دي تذكيرات تنظيمية عامة، مش خطة طبية أو وصفة تمارين لرواد الفضاء. اتبع خطة مهمتك المعتمدة. إتمام المهام مش مقياس للصحة ومش بيحل التنبيهات.')}</p><div class="source-row"><div><strong>${t('No notification permission needed','مش محتاج إذن إشعارات')}</strong><small>${t('Reminders appear while the app is open.','التذكيرات بتظهر أثناء فتح التطبيق.')}</small></div>${icon('bell')}</div><a class="text-link" href="#research">${t('Why these habits matter','ليه العادات دي مهمة؟')}${icon('arrow','ico-arrow')}</a></aside></div>`}
function trendsView(){return `${heading(t('See the bigger picture.','شوف الصورة الأوسع.'),t('Actual timestamps, missing days and metric-specific summaries.','أوقات فعلية وأيام ناقصة وملخص مناسب لكل مؤشر.'))}<div class="notice">${icon('info')}<div>${t('Raw observations and daily summaries are labeled separately. Means are withheld when the metric or recorded context does not support them. No missing readings are invented.','القياسات الأصلية منفصلة عن ملخصات الأيام. لا يظهر متوسط لما المؤشر أو السياق لا يدعمه. لا يتم اختراع قراءات ناقصة.')}</div></div><section class="panel full-chart"><div class="panel-head"><div><h2>${t('Health history','التاريخ الصحي')}</h2><p>${esc(settings.timeZone)}</p></div>${periodControl()}</div>${chartControls()}${renderChart(true)}</section><div class="section-heading" style="margin-top:25px"><h2>${t('More to explore','استكشف أكتر')}</h2><a class="text-link" href="#records">${t('Open measurement history','افتح سجل القياسات')}${icon('arrow','ico-arrow')}</a></div>${recentAlerts()}`}
function bodyView(){const s=systems[system];return `${heading(t('Health, connected.','صحتك، مترابطة.'),t('Select a body system to understand its signals and the science behind them.','اختار جهازًا من الجسم لفهم إشاراته والعلم وراءها.'))}<section class="panel"><div class="body-workspace"><div class="body-large">${bodySVG()}<div class="body-caption">${t('SELECT A MARKER TO EXPLORE','اختار علامة للاستكشاف')}</div></div><div class="system-detail"><div class="system-selector">${Object.entries(systems).map(([k,s])=>`<button data-action="system" data-system="${k}" class="${k===system?'active':''}" aria-label="${t(s.en,s.ar)}" aria-pressed="${k===system}">${icon(s.icon)}</button>`).join('')}</div><span class="eyebrow">${t('BODY SYSTEM','أجهزة الجسم')}</span><h2>${t(s.en,s.ar)}</h2><p>${t(...s.desc)}</p><h3>${t('Your latest measurements','آخر قياساتك')}</h3>${s.keys.length?s.keys.map(k=>{const r=latest(k);return `<div class="system-reading"><span>${metricLabel(k)} ${r?'· '+fmtDate(r.timestamp):''}</span><strong dir="ltr">${r?r.values[k]+' <small>'+METRICS[k].unit+'</small>':'—'}</strong></div>`}).join(''):`<p class="helper-note">${t('No direct bone or muscle assessment is available in this app.','التطبيق لا يقيس كثافة العظام أو قوة العضلات بشكل مباشر.')}</p>`}<h3>${t('How to check in','إزاي تسجّل؟')}</h3><p>${t(...s.guide)}</p><a class="text-link" style="margin-top:12px" href="${s.source}" target="_blank" rel="noopener">${t('Read the source','اقرأ المصدر')}${icon('external')}</a><br><button class="btn btn-primary" data-action="log">${icon('plus')}${t('Record a measurement','سجّل قياسًا')}</button></div></div></section><div class="notice" style="margin-top:20px">${icon('info')}<div>${t('This illustration is an educational navigation tool. Markers do not show a diagnosis, scan, or measured organ health.','الرسم وسيلة تعليمية للتنقّل. العلامات مش تشخيص أو أشعة أو قياس لصحة الأعضاء.')}</div></div>`}


function helpEntry(){return `<aside class="help-entry"><span class="help-entry-icon">${icon('shield')}</span><div><strong>${t('Know your next step.','اعرف خطوتك الجاية.')}</strong><p>${t('Interim guidance, warning signs, and what to tell a clinician.','خطوات مؤقتة، وعلامات خطر، ومعلومات تجهّزها للطبيب.')}</p></div><button class="btn btn-light" data-action="help">${t('What do I do now?','أعمل إيه دلوقتي؟')}${icon('arrow','ico-arrow')}</button></aside>`}
function selectedHelpRecord(){return records.find(r=>r.id===helpRecordId)||null}
function openHelp(id=null){if($('.modal'))closeModal();helpRecordId=records.some(r=>r.id===id)?id:null;helpAnswers={};if(location.hash==='#help')renderMain();else location.hash='help'}
function helpView(){const r=selectedHelpRecord(),g=buildGuidance(r,helpAnswers);return `${heading(t('Know your next step while arranging medical help.','اعرف تتصرف إزاي، لحد المساعدة الطبية.'),t('Adult first-aid information from published sources. No diagnosis or prescription.','معلومات إسعاف أولي عامة للبالغين من مصادر منشورة. بدون تشخيص أو وصف أدوية.'),t('INTERIM MEDICAL GUIDANCE','إرشادات مؤقتة لحد وصول المساعدة'))}<section class="emergency-always" aria-label="${t('Emergency help','المساعدة الطارئة')}">${icon('bell')}<div><strong>${t('Severe symptoms? Get emergency help now.','أعراض خطيرة؟ اطلب مساعدة طارئة فورًا.')}</strong><p>${t('Severe trouble breathing, chest pain, blue/grey lips, sudden confusion, sudden face/arm/speech changes, or unresponsiveness need immediate help. Do not wait for this form, another reading, or a scheduled appointment.','ضيق تنفس شديد، ألم صدر، ازرقاق الشفتين، ارتباك مفاجئ، تغيّر مفاجئ في الوجه أو الذراع أو الكلام، أو فقدان الاستجابة يستلزم مساعدة فورية. ما تستناش الأسئلة أو قياس تاني أو ميعاد كشف.')}</p><small>${t('On Earth: call local emergency services. In a mission: alert the crew medical lead immediately and follow the actual emergency procedure. This app does not make calls or send messages.','على الأرض: اتصل بالطوارئ المحلية. داخل مهمة: نبّه مسؤول طب الطاقم فورًا واتبع إجراءات الطوارئ الفعلية. التطبيق لا يتصل ولا يرسل رسائل.')}</small></div></section><div class="help-grid ${g.level==='emergency'?'emergency-priority':''}"><div><section class="panel panel-pad help-input"><div class="section-heading"><div><h2>${t('1. Choose the observation context','١. اختار سياق القياس')}</h2><p>${t('A saved reading is optional. Your current symptoms take priority.','اختيار تسجيل سابق اختياري. أعراضك الحالية لها الأولوية.')}</p></div></div><label class="field">${t('Saved observation','التسجيل المحفوظ')}<select id="help-record"><option value="">${t('Current symptoms only — no saved reading','أعراض حالية فقط — بدون تسجيل محفوظ')}</option>${[...records].reverse().filter((x,i)=>i<200||x.id===helpRecordId).map(x=>`<option value="${esc(x.id)}" ${x.id===helpRecordId?'selected':''}>${fmtDate(x.timestamp)} · ${fmtTime(x.timestamp)} — ${Object.keys(x.values).map(metricLabel).join(' / ')}</option>`).join('')}</select></label>${r?`<div class="help-observation"><span class="pill ${r.source==='manual'?'green':'blue'}">${sourceName(r.source)}</span><time>${fmtDate(r.timestamp)} · ${fmtTime(r.timestamp)}</time><div>${Object.entries(r.values).map(([k,v])=>`<span><small>${metricLabel(k)}</small><strong dir="ltr">${v} ${METRICS[k].unit}</strong></span>`).join('')}</div></div>`:`<p class="helper-note">${t('No measurements are assumed. You can check warning signs without logging a reading.','مش بنفترض أي قياسات. تقدر تراجع علامات الخطر من غير تسجيل قراءة.')}</p>`}<div class="help-context" aria-label="${t('Where help is being arranged','مكان ترتيب المساعدة')}"><span>${t('Contact context','سياق طلب المساعدة')}</span><div class="segmented">${[['earth','On Earth','على الأرض'],['mission','In a mission','داخل مهمة']].map(([v,en,ar])=>`<button class="${helpContext===v?'active':''}" data-action="help-context" data-context="${v}" aria-pressed="${helpContext===v}">${t(en,ar)}</button>`).join('')}</div></div><p class="helper-note">${t('This selector changes contact instructions only, not medical thresholds or gravity-specific treatment.','الاختيار بيغيّر تعليمات التواصل فقط، مش حدود التنبيه أو علاج خاص بالجاذبية.')}</p></section><section class="panel panel-pad help-symptoms"><div class="section-heading"><div><h2>${t('2. Check current warning signs','٢. راجع علامات الخطر الحالية')}</h2><p>${t('Any “yes” immediately shows emergency instructions.','أي إجابة «نعم» بتظهر إرشادات الطوارئ فورًا.')}</p></div></div>${SYMPTOM_QUESTIONS.map(q=>`<fieldset class="symptom-question"><legend>${t(...q.label)}</legend><p>${t(...q.hint)}</p><div class="symptom-answers">${[['yes','Yes','نعم'],['no','No','لا'],['unknown','Not sure','مش متأكد']].map(([v,en,ar])=>`<button data-action="help-answer" data-question="${q.key}" data-answer="${v}" aria-pressed="${(helpAnswers[q.key]||'unknown')===v}" class="${(helpAnswers[q.key]||'unknown')===v?'selected':''}">${t(en,ar)}</button>`).join('')}</div></fieldset>`).join('')}<p class="helper-note">${t('Answers are temporary, not a diagnosis, and are not added to your saved records. “No” does not rule out a medical emergency. If you feel seriously unwell, seek help regardless of the numbers.','الإجابات مؤقتة وليست تشخيصًا، ومش بتُضاف لسجلك المحفوظ. «لا» لا تستبعد الطوارئ. لو حاسس بتعب شديد، اطلب المساعدة مهما كانت الأرقام.')}</p></section></div><div class="help-result-column"><div id="guidance-announcement" class="sr-only" role="status" aria-live="polite"></div><div id="guidance-result">${helpResult()}</div></div></div><section class="notice" style="margin-top:20px">${icon('info')}<div>${t('General adult Earth-based references, not clinically validated decision support or an approved spaceflight medical protocol. The source links are available online; the written guidance remains available offline after the app has cached. Clinical history, symptoms, prescribed plans and medical advice take priority.','مراجع أرضية عامة للبالغين، وليست نظام قرار مُتحققًا منه طبيًا أو بروتوكولًا معتمدًا لرحلات الفضاء. روابط المصادر تحتاج اتصالًا؛ نص الإرشادات متاح بدون اتصال بعد تخزين التطبيق. التاريخ المرضي والأعراض وخطط الطبيب وتعليماته لهم الأولوية.')}</div></section>`}
function helpResult(){const r=selectedHelpRecord(),g=buildGuidance(r,helpAnswers);const levelNames={emergency:t('EMERGENCY HELP NOW','مساعدة طارئة الآن'),urgent:t('PROMPT MEDICAL CONTACT','تواصل طبي سريع'),review:t('REVIEW & FOLLOW UP','مراجعة ومتابعة'),info:g.symptomsComplete?t('GENERAL GUIDANCE','إرشاد عام'):t('INFORMATION STILL NEEDED','المعلومات لسه غير مكتملة')};return `<section class="guidance-card guidance-${g.level}" data-guidance-level="${g.level}"><div class="guidance-heading"><span class="eyebrow">${levelNames[g.level]}</span><h2>${t(...g.title)}</h2><p>${t(...g.summary)}</p></div>${g.historical?`<div class="historical-notice">${icon('clock')}<span>${t('This reading is more than 24 hours old. It cannot establish your current condition. Current severe symptoms need help now; if an old critical reading is current or still unresolved, seek the indicated help.','القراءة دي أقدم من ٢٤ ساعة، ومش بتحدد حالتك الحالية. الأعراض الخطيرة الحالية تحتاج مساعدة فورًا؛ لو المشكلة المسجّلة ما زالت موجودة أو لم تُراجع طبيًا، اطلب المساعدة الموضّحة.')}</span></div>`:''}<div class="contact-instruction">${icon('shield')}<div><strong>${helpContext==='earth'?t('Contact help on Earth','طلب المساعدة على الأرض'):t('Contact help during a mission','طلب المساعدة داخل المهمة')}</strong><p>${helpContext==='earth'?(g.level==='emergency'?(g.historical&&!Object.values(helpAnswers).includes('yes')?t('For this past critical reading, seek emergency help if the problem is current or still unresolved. A historical value alone cannot show your condition now.','بالنسبة للقراءة الحرجة القديمة، اطلب المساعدة الطارئة لو المشكلة مستمرة أو لم تُراجع طبيًا. الرقم القديم وحده مش بيحدد حالتك الآن.'):t('Call your local emergency service now; ask someone nearby to help and do not drive yourself.','اتصل بالطوارئ المحلية فورًا، واطلب مساعدة شخص قريب، وما تسوقش بنفسك.')):t('Arrange contact with a qualified clinician. If any serious or sudden symptom appears, call local emergency services immediately.','رتّب التواصل مع مختص طبي. لو ظهر عرض شديد أو مفاجئ، اتصل بالطوارئ المحلية فورًا.')):t('Alert the designated crew medical lead. For an emergency, activate the mission’s existing emergency procedure immediately. This app contains no approved mission-specific procedure.','نبّه مسؤول طب الطاقم. عند الطوارئ، فعّل إجراء الطوارئ الموجود بالمهمة فورًا. التطبيق لا يحتوي على إجراء خاص بالمهمة معتمد طبيًا.')}</p><small>${t('No call or message is made by this app.','التطبيق لا يجري مكالمة ولا يرسل رسالة.')}</small></div></div><ol class="guidance-steps">${g.steps.map((step,i)=>`<li><span>${i+1}</span><div><h3>${t(...step.title)}</h3><p>${t(...step.body)}</p></div></li>`).join('')}</ol>${g.avoid.length?`<div class="guidance-avoid"><h3>${t('Avoid these actions','حاجات تتجنّبها')}</h3><ul>${g.avoid.map(x=>`<li>${t(...x)}</li>`).join('')}</ul></div>`:''}${!g.symptomsComplete?`<p class="incomplete-note">${t('Unanswered or uncertain signs remain unknown. This app has not cleared you as safe. Do not delay emergency help to finish answering.','العلامات غير المُجاب عنها أو غير المؤكدة تظل مجهولة. التطبيق لم يقرّر إنك في أمان. ما تأخّرش طلب المساعدة علشان تكمّل الإجابات.')}</p>`:`<p class="incomplete-note">${t('Your answers do not exclude an emergency. Worsening, persistent, or concerning symptoms still need medical advice.','إجاباتك لا تستبعد الطوارئ. الأعراض المتفاقمة أو المستمرة أو المقلقة تحتاج مشورة طبية.')}</p>`}<div class="guidance-sources"><h3>${t('Sources for these steps','مصادر الخطوات دي')}</h3>${g.sources.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.label)}${icon('external')}</a>`).join('')}</div><button class="btn btn-primary handover-button" data-action="help-handover">${icon('download')}${t('Download a clinician handover','نزّل ملخصًا للطبيب')}</button><button class="btn btn-light handover-button" data-action="save-help-case">${icon('records')}${t('Save a case for follow-up','احفظ ملفًا للمتابعة')}</button><p class="helper-note">${t('Includes the selected reading, current answers, timing and source references. Downloading or marking a prompt as seen does not resolve a medical concern.','يشمل القراءة المختارة والإجابات الحالية والوقت والمراجع. التنزيل أو الاطلاع على التنبيه لا يعني حل الحالة الصحية.')}</p></section>`}
function updateHelpResult(){const result=$('#guidance-result');if(!result)return;const before=result.querySelector('[data-guidance-level]')?.dataset.guidanceLevel;result.innerHTML=helpResult();document.querySelectorAll('[data-action="help-answer"]').forEach(b=>{const on=(helpAnswers[b.dataset.question]||'unknown')===b.dataset.answer;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});document.querySelectorAll('[data-action="help-context"]').forEach(b=>{const on=helpContext===b.dataset.context;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});const g=buildGuidance(selectedHelpRecord(),helpAnswers);$('#guidance-announcement').textContent=t(...g.title)+' '+t(...g.summary);$('.help-grid')?.classList.toggle('emergency-priority',g.level==='emergency');if(g.level==='emergency'&&before!=='emergency')requestAnimationFrame(()=>result.scrollIntoView({block:'start',behavior:'instant'}))}
function downloadHandover(){const r=selectedHelpRecord(),g=buildGuidance(r,helpAnswers);const lines=[t('CosmoVital — interim guidance handover','CosmoVital — ملخص الإرشادات المؤقتة'),new Date().toLocaleString(locale()),'',t('Personal observations; not verified measurements or a diagnosis. No information has been sent to a clinician.','تسجيل شخصي؛ ليست قياسات متحققًا منها أو تشخيصًا. لم يتم إرسال معلومات لطبيب.'),t('Contact context: ','سياق التواصل: ')+(helpContext==='earth'?t('Earth','الأرض'):t('Mission','مهمة فضائية')),'',r?t('Selected record: ','التسجيل المختار: ')+new Date(r.timestamp).toLocaleString(locale(),{timeZone:settings.timeZone}):t('No saved reading selected.','لم يتم اختيار قراءة محفوظة.')];if(r){lines.push(sourceName(r.source));for(const [k,v]of Object.entries(r.values))lines.push(metricLabel(k)+': '+v+' '+METRICS[k].unit);if(r.notes)lines.push(t('Notes: ','ملاحظات: ')+r.notes)}lines.push('',t('Current self-reported signs (not saved to health records):','العلامات الحالية المبلّغ عنها (لا تُحفظ في السجل):'));for(const q of SYMPTOM_QUESTIONS){const a=helpAnswers[q.key]||'unknown';lines.push(t(...q.label)+': '+(a==='yes'?t('Yes','نعم'):a==='no'?t('No','لا'):t('Unknown','غير معروف')))}lines.push('',t(...g.title),t(...g.summary));for(const [i,step]of g.steps.entries())lines.push((i+1)+'. '+t(...step.title)+' — '+t(...step.body));lines.push('',t('References:','المراجع:'),...g.sources.map(x=>x.label+' '+x.url),'',t('Adult terrestrial first-aid information. Not a validated mission medical protocol.','معلومات إسعاف أولي أرضية عامة للبالغين. ليست بروتوكولًا طبيًا معتمدًا لمهمة.'));download(lines.join('\n'),'cosmovital-handover-'+new Date().toISOString().slice(0,10)+'.txt','text/plain;charset=utf-8');toast(t('Handover downloaded. Nothing was sent.','تم تنزيل الملخص. لم يتم إرسال أي شيء.'))}

function alertCopy(a){if(lang!=='ar')return [a.title,a.detail];const r=a.record||lastRecord(),v=r?.values||{};const ar={
heart:['مراجعة معدل نبض الراحة','القراءة خارج المرجع العام لنبض البالغين وقت الراحة: ٦٠–١٠٠ نبضة/دقيقة. اللياقة والأدوية والأعراض وسياق المهمة مهمين. أعد التحقق من القياس واتبع بروتوكول طب المهمة.'],
oxygen:['مراجعة تشبع الأكسجين',v.oxygen<=88?'القراءة ٨٨٪ أو أقل. اطلب المساعدة الطبية فورًا حسب بروتوكول طوارئ المهمة. تحقّق من الحساس دون تأخير المساعدة؛ الأعراض الشديدة لها الأولوية.':v.oxygen<=92?'القراءة ٩٢٪ أو أقل. تحقّق سريعًا من تثبيت الحساس وتواصل مع مسؤول الطب حسب بروتوكول المهمة. الأعراض أهم من قراءة الحساس، وأجهزة التأكسج لها حدود في الدقة.':'القراءة أقل من المرجع العام ٩٥–١٠٠٪. تحقّق من تثبيت الحساس وظروف القياس والأعراض واطلب المراجعة الطبية حسب بروتوكول المهمة.'],
sleep:['متابعة النوم','مدة النوم أقل من التوصية العامة للبالغين: ٧ ساعات على الأقل. راجع مواعيد النوم وضغط العمل وحالتك مع الفريق. التسجيل ذاتي وليس تشخيصًا.'],
temp:['مراجعة درجة الحرارة',v.temp<35?'القراءة أقل من ٣٥°م، مرجع انخفاض حرارة الجسم لدى NHS. اطلب المساعدة الطبية سريعًا حسب بروتوكول الطوارئ. تحقق من الوحدة وطريقة القياس دون تأخير المساعدة.':a.severity==='urgent'?'القراءة ٤٠٫٦°م أو أكثر، وهي مرجع اتصال طبي للبالغين لدى MedlinePlus. تواصل سريعًا مع مسؤول الطب؛ طريقة القياس والأعراض واستمرار الحرارة مهمين.':'القراءة ٣٨°م أو أكثر، وهي مرجع شائع للحمى لدى البالغين. موضع القياس والأعراض مهمان. أعد التحقق واتبع بروتوكول المهمة.'],
mood:['متابعة حالتك النفسية','سجّلت شعورًا منخفضًا. فكّر في تواصل خاص مع مسؤول دعم الطاقم أو الفريق الطبي. مقياس المزاج من ١ إلى ٥ تسجيل شخصي وليس تقييمًا نفسيًا معتمدًا.'],
bp:['مراجعة ضغط الدم',a.severity==='urgent'?'وصلت إحدى القراءتين أو كلتاهما لتنبيه التطبيق التحفظي عند ١٨٠ انقباضي / ١٢٠ انبساطي أو أكثر، مستندًا لمرجع AHA الذي يذكر أعلى من هذه القيم. تواصل سريعًا مع مسؤول الطب واتبع بروتوكول المهمة. الأعراض الشديدة تستلزم مساعدة فورية. قراءة واحدة لا تثبت تشخيصًا.':'وصلت إحدى القراءتين أو كلتاهما لمرجع المراجعة العام: ١٣٠ انقباضي / ٨٠ انبساطي. أعد القياس بجهاز وإجراء معتمدين وناقش الاتجاه مع الفريق الطبي. قراءة واحدة لا تثبت تشخيصًا.']};return ar[a.metric]||[a.title,a.detail]}

function reviewAlerts(){return ['heart','oxygen','sleep','temp','mood','sys'].flatMap(k=>{const r=latest(k);return r?assessRecord(r).filter(a=>a.metric===(k==='sys'?'bp':k)).map(a=>({...a,record:r})):[]})}
function recentAlerts(){return healthUI.recentAlerts()}
function matchingRecords(){const q=query.toLowerCase();return [...records].reverse().filter(r=>!q||[r.timestamp,new Date(r.timestamp).toLocaleString(locale(),{timeZone:settings.timeZone}),r.notes,...Object.keys(r.values).map(metricLabel)].join(' ').toLowerCase().includes(q))}
function recordRows(){return healthUI.recordRows()}
function recordsView(){return healthUI.recordsView()}
let researchMetric='heart';
function researchView(){const hazards=[['sun','Space radiation','الإشعاع الفضائي','Exposure can affect long-term health.','التعرّض قد يؤثر على الصحة طويلة الأمد.'],['brain','Isolation & confinement','العزلة والأماكن المغلقة','A different setting for mood, sleep, and teamwork.','ظروف مختلفة للمزاج والنوم والعمل الجماعي.'],['planet','Distance from Earth','البعد عن الأرض','Medical support and communication become harder.','الدعم الطبي والتواصل يصبحان أصعب.'],['body','Gravity fields','اختلاف الجاذبية','Changed loading affects bones, muscles, and fluids.','تغيّر الحمل يؤثر على العظام والعضلات والسوائل.'],['shield','Hostile / closed environments','بيئة مغلقة وعدائية','Habitat conditions shape everyday health.','ظروف المعيشة تؤثر على الصحة اليومية.']];return `${heading(t('Real science. Clear provenance.','علم حقيقي. ومصدر واضح.'),t('Explore verified research without confusing it with your own health data.','استكشف أبحاثًا موثقة، بشكل منفصل عن بياناتك الصحية الشخصية.'),t('RESEARCH & OPEN DATA','الأبحاث والبيانات المفتوحة'))}<div class="notice">${icon('book')}<div><strong>${t('Two distinct kinds of evidence.','نوعان مختلفان من البيانات.')}</strong> ${t('NASA research explains spaceflight risks. The open physiological dataset below contains real ground-based clinical recordings, not astronaut readings. Neither is used as your personal baseline.','أبحاث ناسا بتشرح مخاطر رحلات الفضاء. البيانات الفسيولوجية المفتوحة أدناه تسجيلات سريرية حقيقية على الأرض، وليست قراءات لرواد فضاء. ولا يتم استخدام أي منها كخط أساس شخصي ليك.')}</div></div><div class="research-grid"><article class="research-card"><div class="source-tag">NASA · HUMAN RESEARCH PROGRAM</div><div class="research-number">5<small>${t('hazards','مخاطر')}</small></div><h3>${t('The human side of exploration.','الجانب الإنساني من الاستكشاف.')}</h3><p>${t('An established framework for understanding the environmental challenges of human spaceflight.','إطار علمي لفهم التحديات البيئية لرحلات الفضاء البشرية.')}</p><a class="text-link" href="https://www.nasa.gov/hrp/hazards/" target="_blank" rel="noopener">${t('Explore NASA’s framework','إطار ناسا العلمي')}${icon('external')}</a></article><article class="research-card"><div class="source-tag">PHYSIONET · OPEN PHYSIOLOGICAL DATA</div><div class="research-number">53<small>${t('recordings','تسجيلًا')}</small></div><h3>${t('Measured. Not generated.','مقاسة، وليست مولّدة.')}</h3><p>${t('BIDMC PPG and Respiration Dataset: deidentified recordings from critically ill adults in a terrestrial hospital. The explorer shows recording 01.','مجموعة BIDMC: تسجيلات مجهولة الهوية لمرضى بالغين بالعناية المركزة في مستشفى على الأرض. المستكشف يعرض التسجيل 01.')}</p><a class="text-link" href="https://physionet.org/content/bidmc/1.0.0/" target="_blank" rel="noopener">${t('Read dataset documentation','وثائق مجموعة البيانات')}${icon('external')}</a></article><article class="research-card"><div class="source-tag">COSMOVITAL · DATA INTEGRITY</div><div class="research-number">0<small>${t('fabricated readings','قراءات مختلقة')}</small></div><h3>${t('Know where every number comes from.','اعرف مصدر كل رقم.')}</h3><p>${t('Personal readings are entered or imported by you. Research is clearly labeled, referenced, and kept separate. No simulated sensor stream.','القياسات الشخصية بتدخلها أو بتستوردها بنفسك. الأبحاث منفصلة بوضوح ومرفقة بالمصدر. مفيش بث قياسات وهمي.')}</p><a class="text-link" href="#records">${t('Open your own health records','افتح سجلك الشخصي')}${icon('arrow','ico-arrow')}</a></article></div><div class="section-heading"><div><h2>${t('Open data explorer','مستكشف البيانات المفتوحة')}</h2><p>${t('A real physiological recording, with its context intact.','تسجيل فسيولوجي حقيقي، مع توضيح سياقه.')}</p></div><span class="pill blue">${t('GROUND CLINICAL DATA','بيانات سريرية أرضية')}</span></div><section class="panel full-chart" id="dataset-panel">${datasetPanel()}</section><div class="section-heading" style="margin-top:28px"><div><h2>${t('Published spaceflight findings','نتائج منشورة لرحلات الفضاء')}</h2><p>${t('Real aggregate research, never individual predictions.','نتائج بحثية إجمالية حقيقية، وليست توقعات فردية.')}</p></div></div><div class="research-grid"><article class="research-card"><div class="source-tag">NASA · BONE HEALTH</div><div class="research-number">1–1.5%<small>${t('/ month','/ شهر')}</small></div><h3>${t('A different load on the body.','حمل مختلف على الجسم.')}</h3><p>${t('NASA reports average loss in weight-bearing bone density during missions lasting four to six months. Individual responses vary.','ناسا تذكر متوسط فقدان كثافة العظام الحاملة للوزن خلال رحلات تستمر من أربعة إلى ستة أشهر. الاستجابة بتختلف بين الأفراد.')}</p><a class="text-link" href="https://www.nasa.gov/reference/risk-of-spaceflight-induced-bone-changes/" target="_blank" rel="noopener">${t('NASA research reference','المرجع البحثي من ناسا')}${icon('external')}</a></article><article class="research-card"><div class="source-tag">NATURE · INSPIRATION4</div><div class="research-number">6.7<small>${t('h / night','ساعة / ليلة')}</small></div><h3>${t('Sleep in a new environment.','النوم في بيئة جديدة.')}</h3><p>${t('Published mean in-flight sleep for the four-person Inspiration4 crew. A short-duration cohort finding, not a long-mission sleep target.','متوسط النوم أثناء الرحلة المنشور لطاقم Inspiration4 المكوّن من أربعة أفراد. نتيجة لمجموعة صغيرة في رحلة قصيرة، وليست هدفًا للنوم في رحلة طويلة.')}</p><a class="text-link" href="https://www.nature.com/articles/s41586-024-07648-x" target="_blank" rel="noopener">${t('Read the published study','اقرأ الدراسة المنشورة')}${icon('external')}</a></article><article class="research-card"><div class="source-tag">NASA · OPEN SCIENCE DATA REPOSITORY</div><div class="research-number" style="font-size:31px">OSD-575</div><h3>${t('Human spaceflight, in the open.','أبحاث فضاء بشرية مفتوحة.')}</h3><p>${t('Inspiration4 serum metabolic panels and immune / cardiac cytokine research. A real study catalog entry, separate from personal records and the hospital chart.','أبحاث لوحات الأيض في المصل والسيتوكينات المناعية والقلبية لرحلة Inspiration4. دراسة حقيقية منفصلة عن السجل الشخصي ورسم بيانات المستشفى.')}</p><a class="text-link" href="https://osdr.nasa.gov/bio/repo/data/studies/OSD-575" target="_blank" rel="noopener">${t('Open the study record','افتح سجل الدراسة')}${icon('external')}</a></article></div><div class="section-heading" style="margin-top:30px"><div><h2>${t('Five hazards. One human body.','خمسة مخاطر. جسم إنسان واحد.')}</h2><p>NASA Human Research Program</p></div></div><div class="hazard-grid">${hazards.map(([ic,en,ar,den,dar])=>`<article class="hazard">${icon(ic)}<h3>${t(en,ar)}</h3><p>${t(den,dar)}</p></article>`).join('')}</div><section class="panel panel-pad" style="margin-top:25px"><div class="section-heading"><div><h2>${t('Source library & interpretation','مكتبة المصادر والتفسير')}</h2><p>${t('Official sources. General adult references, not astronaut certification.','مصادر رسمية. مراجع عامة للبالغين، وليست اعتمادًا طبّيًا لرواد الفضاء.')}</p></div>${icon('book')}</div><div class="source-list">${[['NASA Human Research Program','Five hazards of human spaceflight','مخاطر رحلات الفضاء الخمسة','https://www.nasa.gov/hrp/hazards/'],['American Heart Association','Resting heart rate and measurement context','النبض في الراحة وظروف القياس','https://www.heart.org/en/healthy-living/fitness/fitness-basics/target-heart-rates'],['American Heart Association','Blood pressure categories and home monitoring','فئات ضغط الدم والمتابعة المنزلية','https://www.heart.org/en/health-topics/high-blood-pressure/understanding-blood-pressure-readings'],['MedlinePlus · U.S. National Library of Medicine','Pulse oximetry, reference values, and limitations','قياس التأكسج ومراجعه وحدوده','https://medlineplus.gov/lab-tests/pulse-oximetry/'],['CDC','Adult sleep duration recommendations','توصيات مدة النوم للبالغين','https://www.cdc.gov/sleep/about/index.html'],['NHS','Adult fever and temperature context','الحمى لدى البالغين وسياق الحرارة','https://www.nhs.uk/conditions/fever-in-adults/'],['PhysioNet · BIDMC v1.0.0','Original dataset, contributors, and licensing','مجموعة البيانات الأصلية ومساهموها والترخيص','https://physionet.org/content/bidmc/1.0.0/'],['NASA Open Science Data Repository','Discover human spaceflight research; access varies by study','اكتشف أبحاث رحلات الفضاء البشرية؛ الإتاحة تختلف حسب الدراسة','https://osdr.nasa.gov/']].map(([org,en,ar,url])=>`<a class="source-row" href="${url}" target="_blank" rel="noopener"><div><strong>${org}</strong><small>${t(en,ar)}</small></div>${icon('external')}</a>`).join('')}</div><p class="helper-note">${t('CosmoVital is an independent project and is not affiliated with or endorsed by NASA. Clinical review rules use broad terrestrial references. The app does not interpret glucose, HRV, or EDA because timing, device method, and individual baselines are essential. The personal mood scale is not a clinical questionnaire.','CosmoVital مشروع مستقل، غير تابع لناسا وغير معتمد منها. تنبيهات المراجعة تستخدم مراجع أرضية عامة. التطبيق لا يفسر السكر أو HRV أو EDA تلقائيًا لأن التوقيت وطريقة الجهاز والخط الأساسي الشخصي ضرورية. مقياس المزاج الشخصي ليس استبيانًا طبيًا.')}</p></section>`}
function datasetPanel(){if(researchError)return `<div class="empty-state">${icon('info')}<h3>${t('Research file unavailable','ملف البحث غير متاح')}</h3><p>${esc(researchError)}</p><a class="btn btn-light" href="https://physionet.org/content/bidmc/1.0.0/" target="_blank" rel="noopener">${t('Open original source','افتح المصدر الأصلي')}</a></div>`;if(!research)return `<p class="loading-line">${t('Loading the verified open recording…','تحميل التسجيل المفتوح الموثّق…')}</p>`;const points=research.points.filter(p=>Number.isFinite(p[researchMetric])).map(p=>({time:p.seconds*1000,value:p[researchMetric]}));const unit=researchMetric==='oxygen'?'%':researchMetric==='heart'?'bpm':'breaths/min',label=researchMetric==='respiration'?t('Respiratory rate','معدل التنفس'):metricLabel(researchMetric),vals=points.map(p=>p.value),avg=vals.length?(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(1):'—';return `<div class="panel-head"><div><h2>BIDMC · ${t('Recording 01','التسجيل 01')}</h2><p>${t('Real hospital recording · 8 minutes · deidentified adult patient','تسجيل مستشفى حقيقي · ٨ دقائق · مريض بالغ مجهول الهوية')}</p></div><select class="form-control" style="width:auto;font-size:10px;padding:6px" id="research-metric" aria-label="${t('Research measurement','القياس البحثي')}">${[['heart',t('Heart rate','معدل النبض')],['oxygen',t('Blood oxygen','تشبع الأكسجين')],['respiration',t('Respiratory rate','معدل التنفس')]].map(([v,l])=>`<option value="${v}" ${v===researchMetric?'selected':''}>${l}</option>`).join('')}</select></div><div class="dataset-summary"><div>${t('Valid observations','قياسات صالحة')}<strong>${points.length}</strong></div><div>${t('Mean','المتوسط')} · ${unit}<strong>${avg}</strong></div><div>${t('Range','النطاق')} · ${unit}<strong>${Math.min(...vals)} – ${Math.max(...vals)}</strong></div></div><div class="chart-wrap">${makeChart(points,{height:260,label,unit,seconds:true,color:'#648fa5'})}</div><div class="chart-footer"><span>${t('Time since start of recording. Missing values omitted, not interpolated.','الزمن منذ بداية التسجيل. القيم المفقودة تُحذف، ولا يتم تقديرها.')}</span><a href="${esc(research.licenseUrl)}" target="_blank" rel="noopener">${esc(research.license||'Open Data Commons Attribution')} ↗</a></div><div class="panel-pad" style="border-top:1px solid var(--border)"><div class="research-download"><a class="text-link" href="data/bidmc_01_Numerics.csv" download>${icon('download')}${t('Download original CSV','تنزيل CSV الأصلي')}</a><a class="text-link" href="${esc(research.sourceUrl)}" target="_blank" rel="noopener">${t('View source & license','المصدر والترخيص')}${icon('external')}</a></div><p class="helper-note">Pimentel, Johnson, Charlton &amp; Clifton · PhysioNet v1.0.0 · DOI: <a href="https://doi.org/10.13026/C2208R" target="_blank" rel="noopener">10.13026/C2208R</a></p><p class="helper-note">${t('This is research context, not your medical history. Ground hospital data cannot be treated as normal astronaut values. No research observations are copied into your health records.','دي بيانات بحثية، مش سجلك الطبي. بيانات مرضى مستشفى على الأرض لا تمثل القيم الطبيعية لرواد الفضاء. لا يتم نسخ أي قياسات بحثية إلى سجلك الشخصي.')}</p></div>`}
async function loadResearch(){try{const response=await fetch('data/research.json');if(!response.ok)throw new Error('Dataset file could not be loaded.');research=await response.json();if(!Array.isArray(research.points)||!research.points.length)throw new Error('Dataset has no observations.')}catch(e){researchError=e.message}if(view==='research')$('#dataset-panel').innerHTML=datasetPanel()}
function printReport(){return `<div class="report-only"><div class="print-head"><h1>CosmoVital — ${t('Health observation report','تقرير القياسات الصحية')}</h1><p>${esc(settings.name)} · ${environmentName()} · ${new Date().toLocaleString(locale())}</p></div><p>${t('Self-entered or imported observations, not independently verified. Not a diagnosis or a validated mission medical system. No report has been sent to a clinician.','قياسات مدخلة أو مستوردة بدون تحقق مستقل. ليست تشخيصًا أو نظامًا طبيًا معتمدًا للمهمة. لم يتم إرسال التقرير لطبيب.')}</p><h2>${t('Observation history','تاريخ القياسات')}</h2><table><thead><tr><th>${t('Date & time','الوقت والتاريخ')}</th><th>${t('Readings','القياسات')}</th><th>${t('Source / context','المصدر / الظروف')}</th><th>${t('Notes','ملاحظات')}</th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(new Date(r.timestamp).toLocaleString(locale(),{timeZone:settings.timeZone}))}</td><td>${Object.entries(r.values).map(([k,v])=>`${metricLabel(k)}: ${v} ${METRICS[k].unit}`).join('<br>')}</td><td>${sourceName(r.source)} / ${esc(r.context)}</td><td>${esc(r.notes)}</td></tr>`).join('')}</tbody></table><h2>${t('Review prompts from latest available measurements','تنبيهات آخر القياسات المتاحة')}</h2>${lastRecord()?reviewAlerts().map(a=>`<p><strong>${esc(alertCopy(a)[0])}</strong>: ${esc(alertCopy(a)[1])}<br>${esc(a.sourceUrl)}</p>`).join(''):''}<h2>${t('Scientific references','المراجع العلمية')}</h2><p>NASA: https://www.nasa.gov/hrp/hazards/<br>AHA: https://www.heart.org/en/health-topics/high-blood-pressure/understanding-blood-pressure-readings<br>MedlinePlus: https://medlineplus.gov/lab-tests/pulse-oximetry/<br>CDC: https://www.cdc.gov/sleep/about/index.html<br>NHS: https://www.nhs.uk/conditions/fever-in-adults/</p></div>`}
function modal(title,subtitle,body,footer=''){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" data-action="close" aria-label="${t('Close','إغلاق')}">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal input:not([type=file]),.modal select,.modal button')?.focus())}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus?.()}
function nowLocal(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function openLog(id=''){return healthUI.openLog(id)}

function openSavedReview(record){const alerts=assessRecord(record).filter(a=>a.severity==='urgent').map(a=>({...a,record}));modal(t('This reading needs medical attention.','القراءة دي محتاجة انتباه طبي.'),fmtDate(record.timestamp)+' · '+fmtTime(record.timestamp),`<div class="notice orange">${icon('bell')}<div>${t('The check-in you just saved contains an escalation prompt. Symptoms take priority; follow the mission medical protocol. No message has been sent to anyone.','القياسات اللي حفظتها فيها تنبيه يستدعي الانتباه. الأعراض لها الأولوية؛ اتبع بروتوكول طب المهمة. لم يتم إرسال أي رسالة لأي شخص.')}</div></div>${alerts.map(a=>`<div style="margin:18px 0"><h3 style="font-size:13px;margin-bottom:7px">${esc(alertCopy(a)[0])}</h3><p style="font-size:11px;line-height:1.9;color:#947b70">${esc(alertCopy(a)[1])}</p><a class="text-link" style="margin-top:8px" href="${esc(a.sourceUrl)}" target="_blank" rel="noopener">${t('Reference','المصدر')}${icon('external')}</a></div>`).join('')}`,`<p>${t('Saved on this device. Not a diagnosis.','محفوظ على هذا الجهاز. ليس تشخيصًا.')}</p><div class="review-footer-actions"><button class="btn btn-light" data-action="close">${t('Close review','إغلاق المراجعة')}</button><button class="btn btn-primary" data-action="help" data-record="${esc(record.id)}">${t('What do I do now?','أعمل إيه دلوقتي؟')}${icon('arrow','ico-arrow')}</button></div>`)}

function showError(message){const el=document.querySelector('.modal #form-error')||$('#form-error');if(el){el.className='form-error';el.textContent=lang==='ar'?'تعذّر الحفظ: '+message:message;el.scrollIntoView({block:'nearest'})}else toast(message)}
function openImport(){return healthUI.openImport()}
function openSettings(){modal(t('Your mission workspace.','مساحة عمل مهمتك.'),t('A personal profile, stored in this browser.','ملف شخصي، محفوظ في هذا المتصفح.'),`<form id="settings-form"><div class="field-grid"><label class="field full">${t('Display name','الاسم الظاهر')}<input name="name" maxlength="40" value="${esc(settings.name||'Explorer')}" required></label><label class="field">${t('Mission environment','بيئة المهمة')}<select name="environment">${Object.entries(environments).map(([k,n])=>`<option value="${k}" ${settings.environment===k?'selected':''}>${t(...n)}</option>`).join('')}</select></label><label class="field">${t('Mission start','بداية المهمة')}<span>${t('Optional','اختياري')}</span><input type="date" name="start" value="${esc(settings.start||'')}" max="${new Date().toLocaleDateString('en-CA')}"></label></div><div class="field-grid" style="margin-top:18px"><label class="field full">${t('Display time zone (IANA)','منطقة العرض الزمنية (IANA)')}<input name="timeZone" value="${esc(settings.timeZone)}" required placeholder="Africa/Cairo"></label><label class="field">${t('Temperature unit','وحدة الحرارة')}<select name="temperatureUnit">${['°C','°F'].map(u=>`<option ${u===settings.temperatureUnit?'selected':''}>${u}</option>`).join('')}</select></label><label class="field">${t('Glucose unit','وحدة السكر')}<select name="glucoseUnit">${['mg/dL','mmol/L'].map(u=>`<option ${u===settings.glucoseUnit?'selected':''}>${u}</option>`).join('')}</select></label></div><div class="notice" style="margin-top:22px">${icon('info')}<div>${t('The mission environment labels your workspace. It does not change screening thresholds, simulate gravity effects, or create a medical protocol.','بيئة المهمة بتحدد اسم مساحة العمل. مش بتغيّر حدود التنبيه أو بتحاكي تأثير الجاذبية أو بتنشئ بروتوكول طبي.')}</div></div><div class="source-row"><div><strong>${t('Private, by design','خصوصية في التصميم')}</strong><small>${healthStore.getSnapshot().configured?t('Your account data uses Supabase with row-level authorization.','بيانات حسابك تستخدم Supabase بصلاحيات على مستوى الصف.'):t('Local storage in this browser. No cloud account is configured.','تخزين محلي في المتصفح. لا يوجد حساب سحابي مفعّل.')}</small></div>${icon('shield')}</div><div class="source-row"><div><strong>${t('Version 3.0 · account-ready health workspace','الإصدار ٣.٠ · مساحة متابعة مهيأة للحسابات')}</strong><small>${t('Based on the supplied CosmoVital project.','مبني على مشروع CosmoVital المرفوع.')}</small></div>${icon('file')}</div><div id="form-error" role="alert"></div></form>`,`<p>${t('Keep an exported backup of your records.','احتفظ بنسخة مصدّرة من سجلك.')}</p><button class="btn btn-primary" type="submit" form="settings-form">${t('Save workspace','احفظ الإعدادات')}</button>`)}
function openExport(){modal(t('Your records, ready to go.','سجلّك جاهز للتصدير.'),t('Choose a format. No data is sent to a clinician automatically.','اختار التنسيق. مفيش بيانات بتتبعت لطبيب تلقائيًا.'),`<div class="export-options">${[['csv','records','CSV spreadsheet','جدول CSV','Measurements with timestamps, units via column keys, and source labels.','القياسات مع الوقت ومفاتيح الأعمدة والمصدر.'],['json','file','Full JSON backup','نسخة JSON كاملة','A portable copy of your observations for later re-import.','نسخة قابلة لإعادة الاستيراد من القياسات.'],['print','download','Printable health report / PDF','تقرير للطباعة / PDF','Open your browser’s print dialog and choose Save as PDF.','افتح نافذة الطباعة واختار الحفظ كملف PDF.']].map(([v,ic,en,ar,den,dar])=>`<button class="export-option" data-action="download" data-format="${v}">${icon(ic)}<span><strong>${t(en,ar)}</strong><small>${t(den,dar)}</small></span>${icon('chevron')}</button>`).join('')}<button class="export-option" data-action="ws-backup">${icon('shield')}<span><strong>${t('Full workspace backup','نسخة احتياطية لمساحة العمل')}</strong><small>${t('Observations, cases and consultation packets.','القياسات وملفات الحالات والاستشارات.')}</small></span>${icon('chevron')}</button></div><p class="helper-note">${records.length} ${t('observations in your personal record. Research recordings are excluded. Exported health files can contain sensitive information; store and share them carefully.','تسجيلات في سجلك الشخصي. البيانات البحثية غير مضمّنة. الملفات الصحية قد تحتوي على معلومات حساسة؛ احفظها وشاركها بحرص.')}</p>`)}
function download(text,filename,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function deleteRecord(id){if(workspace.linkedCaseCount(id)){toast(t('This observation is linked to a case. Keep it to preserve the case history; export a workspace backup before reorganizing your records.','القياس مرتبط بملف حالة. احتفظ به لحماية تسلسل الملف؛ صدّر نسخة مساحة العمل قبل إعادة تنظيم السجل.'));return}const r=records.find(r=>r.id===id);if(!r)return;modal(t('Remove this observation?','حذف التسجيل ده؟'),fmtDate(r.timestamp)+' · '+fmtTime(r.timestamp),`<p style="font-size:12px;color:#839387">${t('This removes the observation from this browser. Export a backup first if you may need it again.','ده بيحذف التسجيل من المتصفح. صدّر نسخة احتياطية لو ممكن تحتاجه بعد كده.')}</p>`,`<button class="btn btn-light" data-action="close">${t('Keep it','احتفظ بيه')}</button><button class="btn btn-primary" style="background:#ab6059" data-action="confirm-delete" data-id="${esc(id)}">${icon('trash')}${t('Remove observation','احذف التسجيل')}</button>`)}
function navigate(next){if(view==='help'&&next!=='help'){helpAnswers={};helpRecordId=null}view=validViews().has(next)?next:'overview';menuOpen=false;document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.mobile-overlay')?.classList.remove('visible');renderMain();window.scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',async e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return}const target=e.target.closest('[data-action]');if(!target)return;try{if(await account.action(target))return;if(await healthUI.action(target))return;if(await workspace.action(target))return}catch(error){showError(error.message);return}const a=target.dataset.action;if(a==='refresh-account'){try{if(healthStore.getSnapshot().configured)await healthStore.refresh();else await healthStore.reloadLocal();storageError='';records=getRecords();workspace.reload();renderMain()}catch(error){showError(error.message)}return}if(a==='save-help-case'){workspace.openCaseCreate(selectedHelpRecord()?.id||'',helpAnswers);return}if(a==='backdrop'&&e.target!==target)return;if(a==='help')openHelp(target.dataset.record||null);else if(a==='help-answer'){helpAnswers[target.dataset.question]=target.dataset.answer;updateHelpResult()}else if(a==='help-context'){helpContext=target.dataset.context;updateHelpResult()}else if(a==='help-handover')downloadHandover();else if(a==='log')openLog();else if(a==='close'||a==='backdrop')closeModal();else if(a==='settings'){if(account.protected('profile')){location.hash='login'}else openSettings()}else if(a==='language'){lang=lang==='en'?'ar':'en';await persist('cosmovital-language',lang);renderShell()}else if(a==='export')openExport();else if(a==='import')openImport();else if(a==='menu'||a==='menu-close'){menuOpen=a==='menu'?!menuOpen:false;document.querySelector('.sidebar').classList.toggle('open',menuOpen);document.querySelector('.mobile-overlay').classList.toggle('visible',menuOpen)}else if(a==='period'){period=target.dataset.period;renderMain()}else if(a==='metric'){metric=target.dataset.metric;if(view!=='trends')location.hash='trends';else renderMain()}else if(a==='system'){system=target.dataset.system;renderMain()}else if(a==='task'){const today=localDate(),old=doneTasks(),next=old.includes(target.dataset.task)?old.filter(x=>x!==target.dataset.task):[...old,target.dataset.task];const updated={...tasks,[today]:next};if(await persist('cosmovital-tasks-v1',updated)){tasks=updated;renderMain()}}else if(a==='ack'){const next={...ack,[target.dataset.id]:new Date().toISOString()};if(await persist('cosmovital-ack-v1',next)){ack=next;renderMain();toast(t('Marked as seen. This does not resolve the health concern.','تم الاطلاع. ده مش معناه حل الحالة الصحية.'))}}else if(a==='delete')deleteRecord(target.dataset.id);else if(a==='confirm-delete'){try{if(workspace.linkedCaseCount(target.dataset.id))throw new Error(t('This observation is now linked to a case and cannot be removed.','القياس أصبح مرتبطًا بملف حالة ولا يمكن حذفه.'));await commit(records.filter(r=>r.id!==target.dataset.id));closeModal();renderMain();toast(t('Observation removed.','تم حذف التسجيل.'))}catch(error){toast(error.message)}}else if(a==='template')download(toCSV([])+'\r\n','cosmovital-template.csv','text/csv;charset=utf-8');else if(a==='download'){if(storageError){toast(storageError);return}const date=new Date().toISOString().slice(0,10);if(target.dataset.format==='csv')download(toCSV(records),`cosmovital-${date}.csv`,'text/csv;charset=utf-8');else if(target.dataset.format==='json')download(JSON.stringify({schema_version:1,app:'CosmoVital',exported_at:new Date().toISOString(),records},null,2),`cosmovital-${date}.json`,'application/json');else if(target.dataset.format==='print'){closeModal();window.print();return}toast(t('Export downloaded.','تم تنزيل التصدير.'))}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f);try{if(await account.submit(f,fd))return;if(await healthUI.submit(f,fd))return;if(await workspace.submit(f,fd))return;if(f.id==='reading-form'){const values={};for(const k of Object.keys(METRICS)){const val=fd.get(k);if(val!=null&&val!=='')values[k]=val}const r=validateRecord({timestamp:new Date(fd.get('timestamp')).toISOString(),source:'manual',values,notes:fd.get('notes'),context:fd.get('context'),meta:Object.fromEntries(['device','method','repeat','signal','glucoseTiming','temperatureSite'].map(k=>[k,fd.get('meta_'+k)||(['device','method'].includes(k)?'':'unknown')]))});await commit(healthStore.merge([r]));closeModal();renderMain();toast(t('Your check-in is saved on this device.','تم حفظ قياساتك على هذا الجهاز.'));if(assessRecord(r).some(a=>a.severity==='urgent')){const saved=records.find(x=>x.id===r.id)||records.find(x=>x.timestamp===r.timestamp&&x.context===r.context&&x.notes===r.notes&&JSON.stringify(x.values)===JSON.stringify(r.values))||r;openSavedReview(saved)}}else if(f.id==='settings-form'){const name=String(fd.get('name')).trim();if(!name)throw new Error('Enter a display name.');const timeZone=String(fd.get('timeZone'));new Intl.DateTimeFormat('en',{timeZone});const next={name,environment:fd.get('environment'),start:fd.get('start'),timeZone,temperatureUnit:String(fd.get('temperatureUnit')),glucoseUnit:String(fd.get('glucoseUnit'))};if(await persist('cosmovital-settings-v1',next)){settings=next;closeModal();renderShell();toast(t('Workspace saved.','تم حفظ الإعدادات.'))}}else if(f.id==='import-form'){const file=fd.get('file');if(!file||!file.size)throw new Error('Choose a non-empty CSV or JSON file.');if(file.size>5*1024*1024)throw new Error('File exceeds 5 MB.');const incoming=parseImport(await file.text(),file.name),next=mergeRecords(records,incoming),added=next.length-records.length;await commit(next);closeModal();view='records';if(location.hash!=='#records')location.hash='records';else renderMain();toast(t(`${added} observations imported; ${incoming.length-added} duplicates skipped.`,`تم استيراد ${added} تسجيلات؛ وتخطي ${incoming.length-added} تسجيلات مكررة.`))}}catch(error){showError(error.message)}});
document.addEventListener('change',e=>{if(healthUI.change?.(e.target))return;if(e.target.id==='help-record'){helpRecordId=e.target.value||null;helpAnswers={};renderMain();$('#help-record')?.focus()}else if(e.target.id==='chart-metric'){metric=e.target.value;renderMain()}else if(e.target.id==='research-metric'){researchMetric=e.target.value;$('#dataset-panel').innerHTML=datasetPanel()}});
document.addEventListener('input',e=>{if(healthUI.input?.(e.target))return;if(e.target.id==='record-search'){query=e.target.value;$('#record-rows').innerHTML=recordRows()}});
document.addEventListener('keydown',e=>{if(e.target.matches('.body-hotspot')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}if(!$('.modal'))return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focusable=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal select,.modal textarea,.modal a')].filter(x=>x.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
window.addEventListener('storage',async e=>{if(healthStore.getSnapshot().configured)return;await healthStore.reloadLocal?.();if(e.key==='cosmovital-mission-v2'){workspace.reload();renderMain();return}if(e.key==='cosmovital-records-v1'){try{records=getRecords();storageError='';renderMain();toast(t('Records updated from another tab.','تم تحديث السجل من نافذة أخرى.'))}catch(error){storageError=error.message;renderMain()}}});
view=validViews().has(location.hash.slice(1))?location.hash.slice(1):'overview';
healthStore.subscribe(state=>{const oldId=accountUserId;accountUserId=state.user?.id||null;records=state.records;storageError=state.error;workspace.reload();if(state.configured){const preferences=state.profile?.preferences||{};settings=normalizeSettings({...defaultSettings,...preferences,name:state.profile?.display_name||'Explorer'});tasks=preferences.tasks||{};if(oldId!==accountUserId){closeModal();healthUI.clearSensitive();helpAnswers={};helpRecordId=null;query=''}}if(appStarted){if(oldId!==accountUserId)renderShell();else renderMain()}});
let accountUserId=null;
$('#app').innerHTML='<div class="loading-line" role="status">Loading CosmoVital…</div>';
healthStore.initialize().catch(error=>{storageError=error.message}).finally(()=>{records=getRecords();workspace.reload();appStarted=true;if(new URLSearchParams(location.search).get('auth')==='recovery'&&healthStore.getSnapshot().user){view='reset-password';location.hash=view}renderShell()});

if('serviceWorker' in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))}

window.addEventListener('online',()=>{if(appStarted)renderMain()});window.addEventListener('offline',()=>{if(appStarted)renderMain()});
